/** 
 * Event in case of channel mode changes.
 * @param msg channel mode message
 */
@Override public void onChannelMode(ChannelModeMessage msg){
  if (!isThisChatRoom(msg.getChannelName()))   return;
  try {
    processModeMessage(msg);
  } catch (NullPointerException e) {
    // log and continue
  }
}
